function title(){overlay.innerHTML=`<section class="title-cover" aria-labelledby="coverTitle"><img class="cover-art" src="assets/cover-rescue-v2.png" alt="奶蛙用大笑闯向地牢，牛来与美鼠守着关住奶豆的牢笼" fetchpriority="high"><div class="cover-copy"><div class="cover-kicker">池塘奇遇 · 救回奶豆</div><h2 id="coverTitle">奶蛙<span>的结合</span></h2><p class="cover-story">牛来和美鼠抓走了奶豆。<br>这一次，用大笑把孩子带回家。</p><div class="cover-actions"><button class="primary" id="start">出发救奶豆 <span aria-hidden="true">→</span></button><button class="cover-help" id="titleHelp">玩法说明</button></div><p class="cover-hint"><span class="cover-desktop-hint">WASD 移动 · 方向键 / 鼠标四向射击</span><span class="cover-mobile-hint">点击出发自动全屏 · 横屏游玩</span></p></div><span class="cover-edition">THE BINDING OF NAIWA</span></section>`;if(bossDemo){$('#start').firstChild.textContent='开始双 Boss 演示 ';$('.cover-story').innerHTML='直接进入最终房间，试听技能原声。<br>演示中奶蛙无敌，不计入最佳记录。'}$('#start').onclick=start;$('#titleHelp').onclick=help;}
function start(){revivePlayer.stop();voice.stop();bossVoice.stop();itemVoice.stop();soundMix.stopTone();bossVoice.reset();itemVoice.reset();voice.unlock();bossVoice.unlock();itemVoice.unlock();void requestGameFullscreen({mobile:mobileMedia.matches});resetTouchInput();game=new Game();game.start();if(bossDemo){game.floor=5;game.generate();game.enter(game.rooms.find(r=>r.exists&&r.type==='boss').id,'top');game.hurt=()=>{};game.p.damage=3}overlay.innerHTML='';keys.clear();mouse.down=false;updateUI();canvas.focus();beep(650,.15);toast(matchMedia('(pointer:coarse), (max-width:780px), (max-width:1100px) and (max-height:600px)').matches?'左手移动；右手十字摇杆四向射击，滑动换向，松手停止。':'方向键大笑；E 互动；B 炸弹；造成伤害充能，Q 大爆笑击退。')}
function pause(){if(game.mode==='revive'){revivePlayer.pause();return}resetTouchInput();if(['play','rescue'].includes(game.mode)){pauseMode=game.mode;voice.stop();bossVoice.stop();itemVoice.stop();soundMix.stopTone();game.mode='paused';overlay.innerHTML=`<div class="modal"><div class="mini">TAKE A LITTLE BREATH</div><h2>蛙蛙歇一会儿</h2><p>池塘会等你的。</p><button class="primary" id="resume">继续冒险 →</button><button class="secondary" id="restart">重新开始本局</button></div>`;$('#resume').onclick=resume;$('#restart').onclick=start;keys.clear();mouse.down=false;}else if(game.mode==='paused')resume()}
