function help(){if(['help','revive'].includes(game.mode))return;voice.stop();bossVoice.stop();itemVoice.stop();soundMix.stopTone();resetTouchInput();oldMode=game.mode;game.mode='help';overlay.innerHTML=`<div class="modal help-modal"><div class="mini">A FROG'S FIELD GUIDE</div><h2>池塘生存指南</h2><div class="instructions"><b>移动：</b>WASD；手机拖动左侧摇杆。<br><b>攻击：</b>只能向上、下、左、右射击。方向键按住发射；鼠标按住，按所在方位取四向。手机按住右侧十字摇杆的方向持续射击，滑动换向，回到中心或松手停止。<br><b>第二章音响：</b>环形音波找弹缝，扇形连发向侧面躲，低音震荡远离或蛙跳穿环；蓄能结束后可反击。<br><b>最终双 Boss：</b>牛来连撞、跺地震荡与牛角扇射轮换；美鼠夹击陷阱、旋转十字弹与连续扇射轮换。牛鼠合击时弹墙留有绿色通道，但仍要避开牛来红线冲撞；每次冲撞重新预警，Q 爆笑可打断。击败一只后，另一只暴走加强连招。<br><b>第四章拼装奶偶：</b>投怪、缝针连射、十字缝线与上下针墙轮换；沿虚线侧向躲针、斜向离开十字标记带。针墙留有绿色安全走廊；半血后连射加长、缝线会重新瞄准再来一轮。<br><b>第三章分拣巨钳：</b>双臂封路后沿缺口释放弹墙，也会追击砸手、横扫和投放货物列阵；绿色缺口可躲避。半血后传送带加速、货物双向夹击，炸退手臂可打断连招并使本体易伤 50%，持续 3 秒。<br><b>第一章奶瓶：</b>落点警示 1 秒后爆开，圈内受到范围伤害，立即离开警示圈。<br><b>抢奶跑腿怪：</b>红围巾、高速追击、血量较低，优先处理。<br><b>圆肚怪：</b>已取消盾牌；飞扑怪冲刺前会显示红线。站桩炮台射击更频繁；尖啸音箱轮换错位环射、瞄准扇射、旋转十字，虚线预警后发射。<br><b>蛙跳：</b>空格，短暂无敌，冷却 2 秒。<br><b>地形：</b>货箱可用笑声击碎，有 15% 概率掉补给；蓝纹藏宝石炸开必有补给；裂纹石堆需炸弹；铆钉柱不能破坏；深色坑洞不能步行或蛙跳越过，但音波可以飞过。<br><b>房间布局：</b>普通房间通过货箱、岩石、固定柱和坑洞分割路线与火线。怪物攻击会留下短暂危险区域，Boss 房有专属技能机关。<br><b>特色怪：</b>胀奶团死后延迟溅奶；滑奶仔踩奶加速；指挥怪催拍加速队友；回声铃锁定方向三连射；叉车预警后冲锋；投包裹工砸向落点；缝补工会回血给同伴；发条废偶高速追击，接触立即自爆，可提前击杀或蛙跳躲伤害；狱卒放电网；探照眼发射旋转十字弹幕。<br><b>资源路线：</b>每层增加钥匙补给库与封墙藏室。补给库消耗 1 把钥匙，击败4–6 名守卫后获 2 枚炸弹与 3 金币；在裂墙门口按 B 放炸弹、退开，炸开藏室后须清怪并躲避落物 12 秒，才会揭晓随机奖励：金币、钥匙炸弹、回血补给或道具。接应点的 E 回收台可用 2 钥匙换 1 炸弹，或 2 炸弹换 1 钥匙，也能换金币，每层限量；也可消耗 2 点生命换 3 金币（不能致死、护盾不抵扣）；商店还能花金币补货。资源房均为可选路线，清完有 25% 概率为空，75% 获得补给（隐藏藏室随机）；结果只结算一次。<br><b>地图：</b>电脑按 M 打开或关闭地图，查看时暂停战斗；也可按 Esc 关闭。<br><b>探索：</b>清空小怪，走到门口进入相邻房间。<br><b>自己找隐藏房：</b>优先检查地图上被两三间房围住的空位，真藏室不会紧贴 Boss 房或上锁资源房。清房后观察墙中央的细裂纹与碎墙灰，靠近会有提示；用炸弹验证。每层最多 2 处假裂纹，指向紧贴 Boss 房的空位，炸错只会露出实墙。情报可直接标出真房间，但不是入场要求。<br><b>道具：</b>道具房拿随机道具；挑战房随机获得宝箱或三选一道具。普通房间有 40% 概率无掉落，否则只给一种小补给。钥匙开房间和宝箱，金币购买商店道具。<br><b>金币服务：</b>商店可花 4 金币刷新道具（每层 2 次）、5 金币买一次性护盾、4 金币补满爆笑、3 金币买本层隐藏房间情报（仅标出藏室，仍需炸墙；后三项每层各 1 次）。已有护盾、满充能或隐藏藏室已发现时不会扣钱。<br><b>复活：</b>每局可在死亡后观看 10 秒奶龙大笑，完成后手动领取半血复活（奇数生命上限向上取整），附带 3 秒无敌。后台暂停计时，中途放弃不消耗机会，但重新观看从头开始。<br><b>通关：</b>击败最终双 Boss 后，反复按键或点击大笑，打破牢笼；长按不连发。随后奶豆与豆包团聚。<br><b>资源：</b>E 互动，B 放炸弹（会炸伤自己），Q 即时大爆笑，半径 160、伤害 4，将附近敌人与子弹向外推。实际造成 45 点伤害充满一次（电池降到 30），初始空充能；大爆笑本身不返还充能。</div><button class="primary" id="closeHelp">知道啦</button>${creatorLinks()}</div>`;bindCreatorLinks(overlay);$('#closeHelp').onclick=()=>{game.mode=oldMode;if(oldMode==='title')title();else if(oldMode==='choice')showChoices('蛙蛙的战利品 · 选择一个',game.choices);else if(oldMode==='paused'){game.mode=pauseMode;pause()}else if(oldMode==='rescue')showRescue();else if(oldMode==='win'||oldMode==='dead')end(oldMode==='win');else overlay.innerHTML='';canvas.focus()};keys.clear();mouse.down=false;}
function showChoices(title,choices){resetTouchInput();if(['shop','start'].includes(game.room.type)){renderPurchaseDialog(overlay,{game,title,choices,onLeave:()=>{game.leaveChoice();overlay.innerHTML='';canvas.focus()},onChoose:success=>{if(success){overlay.innerHTML='';resetTouchInput();canvas.focus()}processEvents()}});return}overlay.innerHTML=`<div class="modal" style="width:530px"><div class="mini">A LITTLE WEIRD. A LITTLE POWERFUL.</div><h2 style="font-size:23px">${title}</h2><p>${game.room.type==='start'?'按标价消耗资源，每层兑换次数有限。':'道具效果可以叠加；商店补给购买后立即生效。'}</p><div class="choice-list">${choices.map(i=>`<button class="choice" data-item="${i.id}">${itemIcon(i)}<strong>${i.name}</strong><small>${i.desc}</small></button>`).join('')}</div><button class="secondary" id="leaveChoice">暂时不拿 / 离开</button></div>`;$('#leaveChoice').onclick=()=>{game.leaveChoice();overlay.innerHTML='';canvas.focus()};overlay.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>{if(game.choose(b.dataset.item)){overlay.innerHTML='';mouse.down=false;keys.clear();canvas.focus();}processEvents();});}
function end(win){revivePlayer.stop();voice.stop();bossVoice.stop();itemVoice.stop();soundMix.stopTone();resetTouchInput();best=Math.max(best,bossDemo?0:game.kills);try{localStorage.setItem('naiwa-best',String(best))}catch{}const min=Math.floor(game.elapsed/60),sec=Math.floor(game.elapsed%60).toString().padStart(2,'0');overlay.innerHTML=`<div class="modal ${win?'rescue-ending':''}">${win?'<canvas id="rescueScene" width="640" height="260" aria-label="一家团聚"></canvas>':frogSVG}<div class="mini">${win?'A VERY HAPPY ENDING':'EVERY FROG GETS ANOTHER CHANCE'}</div><h2>${win?'奶豆，我们回家！':'奶蛙先躺一会儿'}</h2><p>${win?'牛来与美鼠倒下了。豆包抱住奶豆，一家人终于团聚。':'没关系，下一局又是一只好蛙。'}</p><p>赶走 ${game.kills} 只小怪 · 收集 ${game.items.length} 件道具 · ${min}:${sec}<br>最佳记录 ${best} 只</p>${!win&&canRevive(game)?'<button class="death-revive" id="watchRevive">看奶龙大笑 10 秒 · 半血复活</button><p class="death-revive-note">每局仅一次 · 看完可复活</p>':!win?'<p class="death-revive-note">本局复活机会已使用</p>':''}<button class="primary" id="again">再跳一次 →</button>${creatorLinks()}</div>`;bindCreatorLinks(overlay);$('#again').onclick=start;if($('#watchRevive'))$('#watchRevive').onclick=()=>{voice.stop();bossVoice.stop();itemVoice.stop();soundMix.stopTone();resetTouchInput();revivePlayer.open()};beep(win?850:180,.4,'triangle');}
function updateUI(){prepareChapterArt(game.floor);const p=game.p;$('#hearts').textContent=p.maxHp>(mobileMedia.matches?6:12)?'♥︎ '+p.hp+' / '+p.maxHp:'♥︎'.repeat(p.hp)+'♡'.repeat(p.maxHp-p.hp);$('#hearts').setAttribute('aria-label',`生命 ${p.hp} / ${p.maxHp}`);$('#floor').textContent=`0${game.floor} / ${CHAPTERS[game.floor-1]}`;const names={start:'豆包的接应点',fight:'追踪线索',treasure:'道具房',shop:'补给商店',vault:'钥匙补给库',cache:'封墙藏室',challenge:'挑战房',boss:BOSS_NAMES[game.floor-1]};$('#room').textContent=(game.room.encounterName||names[game.room.type])+(game.room.layoutName?' / '+game.room.layoutName:'')+' · '+(game.room.clear?'门已打开':'清空小怪后开门');$('#killcount').textContent=String(game.kills).padStart(2,'0');$('#explored').textContent=game.rooms.filter(r=>r.visited).length+' / '+game.rooms.filter(r=>r.exists).length;$('#map').innerHTML=game.rooms.map(r=>'<div class="map-cell '+(!r.exists||!r.seen||(r.hidden&&!r.revealed&&!r.visited)?'fog ':r.visited?'visited ':'')+(r.id===game.roomId?'here':'')+'" title="'+(r.seen&&r.exists&&(!r.hidden||r.revealed||r.visited)?(r.encounterName||names[r.type]):'未知')+'">'+(!r.exists||!r.seen||(r.hidden&&!r.revealed&&!r.visited)?'':r.id===game.roomId?'●':r.type==='treasure'?'✧':r.type==='shop'?'¤':r.type==='vault'?'⚿':r.type==='cache'?'✹':r.type==='boss'?'♛':r.type==='challenge'?'!':'·')+'</div>').join('');updateMiniMap();updateStats(game);$('#itemcount').textContent=game.items.length+' 件';$('#inventory').innerHTML=game.items.length?game.items.map(id=>{const i=ITEMS.find(i=>i.id===id);return `<div class="item-row"><div class="item-icon">${itemIcon(i)}</div><div><strong>${i.name}</strong><small>${i.short}</small></div></div>`}).join(''):'<div class="empty-bag">✧<p>现在还是一只普通奶蛙。<br>去找到你的第一件怪东西。</p></div>';}
